<section class="page-heading"><div class="eyebrow">ВЫБЕРИТЕ ИГРУ</div><h1><?= htmlspecialchars($title,ENT_QUOTES,'UTF-8') ?></h1></section>
<form class="filters" method="get" action="/catalog"><label>Категория <select name="category"><option value="">Все категории</option><?php foreach($categories as $category): ?><option value="<?= $category->id ?>" <?= $selectedCategory===$category->id?'selected':'' ?>><?= htmlspecialchars($category->name,ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label><label>Сортировка <select name="sort"><option value="name" <?= $sort==='name'?'selected':'' ?>>По названию</option><option value="price_asc" <?= $sort==='price_asc'?'selected':'' ?>>Сначала дешевле</option></select></label><button class="button">Применить</button></form>
<section class="product-grid"><?php foreach($products as $product): ?><article class="product-card"><div class="product-placeholder">♟</div><div class="eyebrow"><?= htmlspecialchars($product->categoryName,ENT_QUOTES,'UTF-8') ?></div><h2><?= htmlspecialchars($product->name,ENT_QUOTES,'UTF-8') ?></h2><p><?= htmlspecialchars($product->description,ENT_QUOTES,'UTF-8') ?></p><strong><?= $product->formattedPrice() ?></strong><a class="text-link" href="/product?id=<?= $product->id ?>">Подробнее</a><form method="post" action="/cart/add"><input type="hidden" name="product_id" value="<?= $product->id ?>"><button class="button">В корзину</button></form></article><?php endforeach; ?><?php if($products===[]): ?><p>В этой категории пока нет товаров.</p><?php endif; ?></section>
